export const DEFAULT_IMAGE_MODEL = "google/gemini-3-pro-image";
export const DEFAULT_VIDEO_MODEL = "bytedance/seedance-2.5";

export function findImageModel(id: string): ImageModel | undefined {
  return IMAGE_MODELS.find((m) => m.id === id);
}
export function findVideoModel(id: string): VideoModel | undefined {
  return VIDEO_MODELS.find((m) => m.id === id);
}

/** Allowed durations for a video model as a flat list (for steppers / validation). */
export function allowedDurations(m: VideoModel): number[] {
  if ("options" in m.durations) return m.durations.options;
  const { min, max, step = 1 } = m.durations;
  const out: number[] = [];
  for (let d = min; d <= max; d += step) out.push(d);
  return out;
}

/** Clamp/snap a requested duration to the nearest allowed value. */
export function snapDuration(m: VideoModel, requested: number): number {
  const list = allowedDurations(m);
  let best = list[0] ?? m.defaultDuration;
  for (const d of list) if (Math.abs(d - requested) < Math.abs(best - requested)) best = d;
  return best;
}

export function estimateImageCost(m: ImageModel, size: ImageModel["sizes"][number], count: number): number | undefined {
  const per = m.estCostUsd[size] ?? m.estCostUsd["1K"];
  return per === undefined ? undefined : per * count;
}

export function estimateVideoCost(m: VideoModel, duration: number, resolution?: VideoModel["resolutions"][number]): number | undefined {
  const res = resolution ?? m.defaultResolution ?? m.resolutions[0];
  const per = res ? m.estCostPerSecUsd[res] : undefined;
  return per === undefined ? undefined : per * duration;
}

